def transform(grid):
    rows, cols = len(grid), len(grid[0])
    occupied = frozenset((r, c) for r in range(rows) for c in range(cols) if grid[r][c] != 0)

    # The figure is tiled by 2x2 squares (color 1) and L trominoes.
    # L color is determined by the missing corner: TL=2, BL=3, TR=4, BR=5.
    tiles = []
    for r in range(rows - 1):
        for c in range(cols - 1):
            square = frozenset((r + dr, c + dc) for dr in range(2) for dc in range(2))
            tiles.append((square, 1))
            for missing, color in (((0, 0), 2), ((1, 0), 3), ((0, 1), 4), ((1, 1), 5)):
                cells = frozenset((r + dr, c + dc) for dr in range(2) for dc in range(2)
                                  if (dr, dc) != missing)
                tiles.append((cells, color))

    choices = {cell: [tile for tile in tiles if cell in tile[0]] for cell in occupied}

    @lru_cache(None)
    def cover(remaining):
        if not remaining:
            return ()
        cell = min(remaining)
        for cells, color in choices[cell]:
            if cells <= remaining:
                rest = cover(remaining - cells)
                if rest is not None:
                    return ((cells, color),) + rest
        return None

    solution = cover(occupied)
    if solution is None:
        raise ValueError('Input cannot be tiled by the task shapes')
    output = [[0] * cols for _ in range(rows)]
    for cells, color in solution:
        for r, c in cells:
            output[r][c] = color
    return output
